from lib import *
S = SS('h8')
steps = [
    step("快的生产者加慢的消费者:服务端连续 Send 64 KiB 的消息,客户端每收一条睡 30 ms。服务端前 20 次 Send 的耗时(ms):0.0、0.5、0.3、0.4,然后从第 5 次起每次都在 30–33 ms(31.3、30.9、30.7、30.6、31.2……)。前 4 次 Send 瞬间返回(数据进了传输层缓冲和窗口),之后服务端被客户端的消费速度“拖住”,每次 Send 要等到客户端读走一条消息、放出窗口才能返回。客户端 1292 ms 内收了 40 条,服务端此时只比它多 Send 完成 3 条(43 条)。这就是流控让快的生产者自动慢下来。", t=tl(S(1)), done=lidx(S(1), '服务端前 20 次 Send'), mark=lidx(S(1), '客户端 1292 ms'), b=bars([['前 4 次 Send 耗时 ms', 0.5, '≈0.4'], ['第 5 次起每次 Send 耗时 ms', 31.3, '≈31'], ['消费者每条睡 ms', 30, '30']], 32, done=[0], mark=[1, 2]), kv=KV([['前 4 次 Send', '约 0.4 ms,瞬间返回'], ['之后每次', '约 31 ms,跟着消费者的节奏'], ['客户端 1292 ms 收 40 条', '服务端只比它多 3 条']], ['之后每次'])),
    step("客户端完全不 Recv 时,服务端能 Send 多少字节才阻塞(1 KiB 的消息逐条发):600 ms 时已成功 Send 195584 字节(191 条),再过 300 ms 还是 195584 字节,说明已经阻塞;取消之后服务端的 Send 返回 “rpc error: code = Canceled desc = context canceled”。默认设置下,不读数据的客户端能让服务端先发出约 191 KiB(默认窗口 64 KiB 的 3 倍)。grpc-go 源码里 internal/transport/defaults.go 的 defaultWriteQuota 是 64 * 1024——每个流在被冲刷之前可以排队的字节数;阻塞点是 流控窗口 加 这个写配额 的叠加。", t=tl(S(2)), done=lidx(S(2), '默认窗口:600 ms 时'), b=bars([['阻塞前 Send 成功字节(千)', 195.584, '195.6'], ['默认窗口 64 KiB(千)', 65.536, '65.5']], 200, done=[0]), kv=KV([['不 Recv', '服务端 Send 195584 字节后阻塞'], ['写配额', 'defaultWriteQuota = 64 KiB(读源码)'], ['阻塞点', '流控窗口 + 写配额(推断)']], ['阻塞点'])),
    step("把客户端接收窗口调大(WithInitialWindowSize 和 WithInitialConnWindowSize),不 Recv 时阻塞前服务端能多 Send 多少:窗口 65536 字节,Send 了 130048 字节(2.0 倍窗口);窗口 262144,324608(1.2 倍);窗口 1048576,1102848(1.1 倍);窗口 4194304,4214784(1.0 倍)。阻塞点大致是“窗口 + 不到 64 KiB 的写缓冲”。默认(没设)窗口时是 195584,比显式设 64 KiB 的 130048 还多,因为显式设置窗口会关闭动态窗口:读源码,dialoptions.go 里这几个选项都会把 StaticWindowSize 设成 true,从而不创建 BDP 估计器。", t=tl(S(3)), done=lidx(S(3), '窗口 4194304'), mark=lidx(S(3), '窗口 65536'), b=bars([['窗口 64 KiB → 阻塞前(千)', 130.048, '130.0'], ['窗口 256 KiB(千)', 324.608, '324.6'], ['窗口 1 MiB(千)', 1102.848, '1102.8'], ['窗口 4 MiB(千)', 4214.784, '4214.8']], 4300, mark=[0], done=[3]), kv=KV([['阻塞点', '约 窗口 + 不到 64 KiB'], ['显式设窗口', 'StaticWindowSize = true,关闭 BDP 动态窗口(读源码)'], ['默认', '195584,动态窗口会在运行中调大']], ['显式设窗口'])),
    step("Send 阻塞时流的 deadline(400 ms)到了:服务端被阻塞的第 3 次 Send(0 起算)返回 “rpc error: code = Canceled desc = context canceled”。注意错误码是 Canceled,而不是 DeadlineExceeded——服务端的 ctx 在超时时被取消。被阻塞的 Send 在 deadline 到期之前不会返回;客户端放弃后(取消或超时)才会解除。服务端流 handler 里的 Send 返回错误就必须马上退出(上一篇)。", t=tl(S(4)), done=lidx(S(4), '服务端:第 3 次 Send 失败'), b=bars([['deadline ms', 400, '400'], ['已成功 Send 的 64 KiB 消息', 3, '3']], 410, done=[1]), kv=KV([['被阻塞的 Send', '直到 deadline/取消才返回'], ['返回的错误', 'Canceled(不是 DeadlineExceeded)'], ['处理', 'Send 报错就 return']], ['返回的错误'])),
    step("服务端 Send 完 100 条消息(每条 20000 字节)后立刻返回 Aborted(Send 都已返回,handler 早已结束),客户端等了 300 ms 才开始读:仍然收到完整的 100 条,顺序正确,最后得到 code=Aborted message=“发完就报错”。已经交给传输层的消息在 handler 返回后仍会被送达,状态放在这些消息之后的 trailers 里——先有消息,后有状态(第 4 篇)。", t=tl(S(5)), done=lidx(S(5), '客户端收到 100 条'), b=bars([['服务端 Send 的消息', 100, '100'], ['客户端收到的消息', 100, '100']], 105, done=[0, 1]), kv=KV([['handler 先返回', '消息仍然全部送达'], ['顺序', '正确'], ['最后', 'Aborted(trailers 在消息之后)']], ['handler 先返回'])),
    step("一个流上并发调用 Send:grpc-go 的源码文档(stream.go)写明 “it is not safe to call SendMsg on the same stream in different goroutines”,但我在实验里让两个 goroutine 各 Send 200 条,客户端收到 400 条,内容与编号全部对得上(0 条损坏)。没有观察到问题不代表它是安全的——文档说不安全,按文档来:同一个流的 Send 要么只在一个 goroutine 里,要么自己加锁(可以用 -race 检测)。", t=tl(S(6)), done=lidx(S(6), '两个 goroutine 各 Send 200 条'), b=bars([['收到的消息', 400, '400'], ['内容损坏', 0, '0']], 410, done=[0, 1]), kv=KV([['文档', '同一个流的 SendMsg 不能在不同 goroutine 并发调用'], ['实验', '2×200 条,0 条损坏(没触发问题)'], ['做法', '单个 goroutine 或加锁']], ['做法'])),
]
A = mkarth('h8', 8, 'gRPC,服务端流,流控,慢消费者,窗口,背压,Go,真实验证,动画演示',
    '服务端流的流控实测:快生产者遇到慢消费者,Send 从 0.4 ms 变成 31 ms 跟着消费者走;不读数据时默认只能先发 195584 字节;调大接收窗口可以多发,窗口选项会关闭动态窗口;被阻塞的 Send 在取消后返回 Canceled;handler 返回后已发的消息仍会送达。',
    '服务端流里,服务端发得比客户端读得快会怎样?Send 在什么时候阻塞?窗口调大有用吗?阻塞时超时怎么处理?这篇用慢消费者实验一项项量。',
    [('0.4 对 31 ms', '服务端前 4 次 Send 与第 5 次起每次 Send 的耗时(消费者每条睡 30 ms)'), ('195584 字节', '客户端不读时,默认设置下服务端阻塞前能 Send 的字节数'), ('64 KiB', 'grpc-go 每个流的 defaultWriteQuota(读源码)')],
    [('背压', '<p>Send 不是“放进队列就走”:传输层只允许每个流有有限的缓冲和流控窗口。前几条消息瞬间返回,之后 Send 要等客户端读走数据放出窗口才返回,生产者自动被消费者拖慢。</p>'),
     ('阻塞点', '<p>客户端完全不读时,默认设置下服务端先发出约 191 KiB 就阻塞。阻塞点约等于流控窗口加不到 64 KiB 的写缓冲(defaultWriteQuota)。</p>'),
     ('调窗口', '<p>显式设置 WithInitialWindowSize 或 WithInitialConnWindowSize 后,阻塞点相应上移(1 MiB 窗口阻塞前约 1.1 MiB);同时会关闭 BDP 动态窗口,所以默认值有时反而更大。窗口怎么影响吞吐见第 10 篇。</p>'),
     ('阻塞时的超时', '<p>被阻塞的 Send 要等到客户端放弃才返回,错误码是 Canceled。流式 handler 必须检查 Send 的返回值并退出。</p>'),
     ('先消息后状态', '<p>handler 返回后,已经交给传输层的消息仍会全部送达,状态在最后。</p>'),
     ('并发 Send', '<p>官方文档说同一个流的 SendMsg 不能在多个 goroutine 里并发;实验没触发问题,不能当作安全的证据。</p>')],
    steps,
    [ENV_H + '。第一节的 Send 耗时是服务端自己用 time.Now 量的;第二、三节用“600 ms 内成功 Send 的字节数”表示阻塞点,不 Recv 的客户端;“defaultWriteQuota”“StaticWindowSize”“SendMsg 并发”三点是读了 grpc-go v1.84.0 源码(internal/transport/defaults.go、dialoptions.go、stream.go)得到的;其余是测量结果',
     '没有验证:阻塞点具体由哪几部分相加(流窗口、连接窗口、写配额、操作系统 socket 缓冲)——只有总数;动态窗口 BDP 把窗口调到多大;多个流共享连接窗口时的分配;客户端 Recv 的内部缓冲;非 grpc-go 实现的阻塞点'],
    '流控与慢消费者')
